# Provenance of the jPomiar datasets — both are SYNTHETIC, generated by this script.
#
# UWAGA: kolejnosc losowan ma znaczenie — kazde rnorm/mvrnorm przesuwa strumien,
# wiec nie wstawiaj nowych losowan miedzy istniejace. Dopisuj na koncu.
#
# Run from the jPomiar/ directory:  Rscript data-raw/datasets.R

set.seed(2026)

# --- 1. Inzynieria srodowiska: azotany w roztworze wzorcowym -----------------
# Laboratorium oczyszczalni sprawdza metode spektrofotometryczna na certyfikowanym
# roztworze wzorcowym o wartosci 50,00 mg/L przed seria oznaczen w sciekach.
# Rozrzut odpowiada powtarzalnosci metody, srednia jest lekko zawyzona — to bias,
# ktory swiadectwo opisuje jako poprawke -0,15 mg/L.
n1 <- 20
azotany <- data.frame(
    pomiar     = seq_len(n1),
    stezenie_mgL = round(rnorm(n1, mean = 50.18, sd = 0.12), 2)
)
write.csv(azotany, "data/azotany.csv", row.names = FALSE)

# --- 2. Inzynieria bezpieczenstwa: lokalizacja poszkodowanego (GNSS) ---------
# Lokalizator ratowniczy podaje kolejne wyznaczenia pozycji tego samego,
# nieruchomego poszkodowanego. Wspolrzedne to odchylki w metrach od punktu
# odniesienia przyjetego przez kierujacego akcja. Rozrzut ~4 m odpowiada
# odbiornikowi w telefonie; skladowe sa skorelowane (geometria satelitow),
# wiec elipsa jest pochylona, a jej os glowna wskazuje kierunek najgorszej
# dokladnosci — to jest obszar, ktory trzeba przeszukac.
n2   <- 30
sdE  <- 4.2
sdN  <- 2.8
rho  <- 0.55
zE <- rnorm(n2)
zN <- rnorm(n2)
wschod  <- 4.8 + sdE * zE
polnoc  <- -3.2 + sdN * (rho * zE + sqrt(1 - rho^2) * zN)
lokalizacja <- data.frame(
    wschod_m = round(wschod, 2),
    polnoc_m = round(polnoc, 2)
)
write.csv(lokalizacja, "data/lokalizacja.csv", row.names = FALSE)

cat("azotany:     n =", nrow(azotany), "\n")
cat("lokalizacja: n =", nrow(lokalizacja), "\n")
